    private static final Map<String, BufferedImage> CACHE_GAMBAR = new HashMap<>();

    // Mencari gambar di beberapa lokasi umum; null kalau tidak ketemu
    private static BufferedImage muatGambar(String nama) {
        if (nama == null) {
            return null;
        }
        if (CACHE_GAMBAR.containsKey(nama)) {
            return CACHE_GAMBAR.get(nama);
        }

        List<File> folder = new ArrayList<>();
        File kerja = new File(System.getProperty("user.dir", "."));
        folder.add(new File(kerja, "gambar"));
        folder.add(new File(kerja, "src/gambar"));
        folder.add(kerja);
        try {
            File kode = new File(chatbotcafedialog.class.getProtectionDomain()
                    .getCodeSource().getLocation().toURI());
            File dasar = kode.isDirectory() ? kode : kode.getParentFile();
            for (int i = 0; i < 3 && dasar != null; i++) {
                folder.add(new File(dasar, "gambar"));
                dasar = dasar.getParentFile();
            }
        } catch (Exception ignored) {
            // lokasi kelas tidak diketahui, lanjut dengan folder lain
        }

        BufferedImage hasil = null;
        for (File f : folder) {
            File berkas = new File(f, nama);
            if (berkas.isFile()) {
                try {
                    hasil = ImageIO.read(berkas);
                } catch (Exception ignored) {
                    hasil = null;
                }
                if (hasil != null) {
                    break;
                }
            }
        }
        // tidak ada file luar: pakai foto yang tertanam di kode
        if (hasil == null && FotoTertanam.DAFTAR.containsKey(nama)) {
            try {
                byte[] bytes = Base64.getDecoder().decode(
                        String.join("", FotoTertanam.DAFTAR.get(nama)));
                hasil = ImageIO.read(new ByteArrayInputStream(bytes));
            } catch (Exception ignored) {
                hasil = null;
            }
        }
        CACHE_GAMBAR.put(nama, hasil);
        return hasil;
    }

