    private void kirimPesan() {

        String teksAsli = inputPesan.getText().trim();

        String pertanyaan =
                inputPesan.getText().toLowerCase().trim();

        if (pertanyaan.isEmpty()) {
            return;
        }

        inputPesan.setText("");

        kirimTeks(teksAsli, pertanyaan);
    }

    // Menampilkan pesan user (kanan), lalu balasan bot (kiri)
    private void kirimTeks(String teksTampil, String pertanyaan) {

        // Riwayat percakapan (sebelum pesan ini) untuk konteks AI
        final List<String[]> konteksRiwayat = ambilRiwayatUntukAI();

        tambahPesan(teksTampil, true);

        final String jawaban = getJawaban(pertanyaan);
        final String cadanganKalauAiGagal = saranCadangan != null ? saranCadangan : jawaban;
        final boolean perluAI = jawaban.startsWith(AWAL_JAWABAN_TIDAK_TAHU);
        final boolean soalMenu = apakahJawabanMenu(jawaban)
                && muatGambar(FOTO_MENU) != null;
        // Foto suasana hanya ikut kalau JAWABANNYA memang tentang suasana
        final boolean soalSuasana = (jawaban.equals(jawabanSuasana())
                || jawaban.equals(JAWABAN_NONGKRONG))
                && muatGambar("suasana1.jpg") != null;
        final boolean soalDelivery = jawaban.equals(jawabanDelivery())
                && muatGambar(FOTO_GOFOOD) != null;

        // Indikator "sedang mengetik" tetap tampil selama AI menyusun jawaban.
        final JPanel barisMengetik = buatBaris(
                new BubblePanel("", false, null, true), false);
        panelPesan.add(barisMengetik);
        refreshDanScroll();

        if (perluAI) {
            final String pesanAsli = teksTampil;
            final String konteksCafe = bangunKonteksAI();
            SwingWorker<String, Void> worker = new SwingWorker<String, Void>() {
                @Override
                protected String doInBackground() throws Exception {
                    return AiLokal.chat(pesanAsli, konteksRiwayat, konteksCafe);
                }

                @Override
                protected void done() {
                    panelPesan.remove(barisMengetik);
                    String hasil;
                    try {
                        hasil = get();
                        if (hasil == null || hasil.trim().isEmpty()
                                || !jawabanAiAman(hasil)) {
                            hasil = cadanganKalauAiGagal;
                        }
                    } catch (Exception ex) {
                        // Ollama mati / lambat: pelanggan tetap dapat jawaban yang jelas
                        System.err.println("[AI lokal] gagal: " + ex);
                        hasil = cadanganKalauAiGagal;
                    }
                    tambahPesan(hasil, false);
                    inputPesan.requestFocusInWindow();
                }
            };
            worker.execute();
            return;
        }

        Timer jeda = new Timer(750, e -> {
            panelPesan.remove(barisMengetik);
            if (soalMenu) {
                tambahPesan("Ini foto menu Café Dialog 📋\n"
                        + "(klik gambar untuk memperbesar)", false, FOTO_MENU);
            }
            if (soalSuasana) {
                tambahPesan("Ini suasana Café Dialog 📸\n"
                        + "(klik foto untuk memperbesar)", false, FOTO_SUASANA);
            }
            if (soalDelivery) {
                tambahPesan(jawaban, false, FOTO_GOFOOD);
            } else {
                tambahPesan(jawaban, false);
            }
            inputPesan.requestFocusInWindow();
        });
        jeda.setRepeats(false);
        jeda.start();
    }

    // Maksimal 6 pesan terakhir, tiap pesan dipotong supaya prompt AI tetap ringan
    private List<String[]> ambilRiwayatUntukAI() {
        List<String[]> hasil = new ArrayList<>();
        int mulai = Math.max(0, riwayat.size() - 8);
        for (int i = mulai; i < riwayat.size(); i++) {
            Pesan p = riwayat.get(i);
            if (p.teks == null || p.teks.trim().isEmpty() || p.teks.equals(TEKS_SAMBUTAN)) {
                continue;
            }
            if (!p.dariUser && (p.teks.contains("---")
                    || p.teks.startsWith(AWAL_JAWABAN_TIDAK_TAHU))) {
                continue;
            }
            String isi = p.teks.length() > 400 ? p.teks.substring(0, 400) + "..." : p.teks;
            hasil.add(new String[]{p.dariUser ? "user" : "assistant", isi});
        }
        return hasil;
    }

