    // Tolak jawaban AI yang menyebut harga / nomor yang tidak ada di data
    private boolean jawabanAiAman(String hasil) {
        if (hasil.length() > 1500) {
            return false;
        }
        // jawaban yang berputar-putar (kalimat sama diulang 3 kali atau lebih)
        String[] kalimat = hasil.split("(?<=[.!?])\\s+");
        Map<String, Integer> hitung = new HashMap<>();
        for (String k : kalimat) {
            String kunci = k.trim().toLowerCase();
            if (kunci.length() > 8 && hitung.merge(kunci, 1, Integer::sum) >= 3) {
                return false;
            }
        }
        // Harga & nomor hanya diperiksa kalau jawaban membahas menu / Café Dialog,
        // supaya jawaban umum (misalnya hitungan uang) tidak ikut ditolak.
        boolean soalCafe = hasil.contains("Café Dialog") || hasil.toLowerCase().contains("cafe dialog");
        for (String nama : daftarHarga().keySet()) {
            if (hasil.toLowerCase().contains(nama.toLowerCase())) {
                soalCafe = true;
                break;
            }
        }
        if (!soalCafe) {
            return true;
        }
        Set<String> hargaSah = new HashSet<>();
        for (String h : daftarHarga().values()) {
            hargaSah.add(h.replaceAll("\\D", ""));
        }
        Matcher mt = Pattern.compile("Rp\\s?([\\d.]+)").matcher(hasil);
        while (mt.find()) {
            if (!hargaSah.contains(mt.group(1).replaceAll("\\D", ""))) {
                return false;
            }
        }
        Matcher nomor = Pattern.compile("\\d{9,}").matcher(hasil.replaceAll("[ \\-]", ""));
        while (nomor.find()) {
            if (!nomor.group().equals("085789678022")) {
                return false;
            }
        }
        return true;
    }

    // Hapus semua percakapan dan mulai dari sambutan lagi
    private void mulaiUlang() {
        riwayat.clear();
        renderUlang();
        tambahPesan(TEKS_SAMBUTAN, false);
        inputPesan.requestFocusInWindow();
    }

