    private void tambahPesan(String teks, boolean dariUser) {
        tambahPesan(teks, dariUser, null);
    }

    private void tambahPesan(String teks, boolean dariUser, String gambar) {
        Pesan p = new Pesan(teks, dariUser, gambar);
        riwayat.add(p);
        panelPesan.add(buatBarisPesan(p));
        refreshDanScroll();
    }

    private JPanel buatBarisPesan(Pesan p) {
        return buatBaris(new BubblePanel(
                p.teks, p.dariUser, p.waktu, false, p.gambar), p.dariUser);
    }

    private JPanel buatBaris(BubblePanel bubble, boolean dariUser) {
        JPanel baris = new JPanel(new BorderLayout());
        baris.setOpaque(false);
        baris.setBorder(BorderFactory.createEmptyBorder(3, 4, 3, 4));

        if (dariUser) {
            baris.add(bubble, BorderLayout.EAST);
        } else {
            // avatar kecil di sebelah kiri bubble bot
            JPanel wadahAvatar = new JPanel(new BorderLayout());
            wadahAvatar.setOpaque(false);
            wadahAvatar.add(new AvatarPanel(30), BorderLayout.NORTH);

            JPanel kiri = new JPanel(new BorderLayout(6, 0));
            kiri.setOpaque(false);
            kiri.add(wadahAvatar, BorderLayout.WEST);
            kiri.add(bubble, BorderLayout.CENTER);
            baris.add(kiri, BorderLayout.WEST);
        }

        baris.setMaximumSize(new Dimension(
                Integer.MAX_VALUE, baris.getPreferredSize().height));
        return baris;
    }

    private JPanel buatPemisahHari() {
        RoundedPanel pil = new RoundedPanel(10, new Color(255, 255, 255, 190));
        pil.setBorder(BorderFactory.createEmptyBorder(3, 12, 3, 12));
        String hari = new SimpleDateFormat("EEEE, d MMMM",
                new java.util.Locale("id", "ID")).format(new Date()).toUpperCase();
        JLabel l = new JLabel(hari);
        l.setFont(new Font(NAMA_FONT, Font.BOLD, 10));
        l.setForeground(new Color(120, 100, 85));
        pil.add(l);

        JPanel baris = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 4));
        baris.setOpaque(false);
        baris.add(pil);
        baris.setMaximumSize(new Dimension(
                Integer.MAX_VALUE, baris.getPreferredSize().height));
        return baris;
    }

    // Gambar ulang semua bubble (dipakai saat ukuran jendela berubah)
    private void renderUlang() {
        panelPesan.removeAll();
        panelPesan.add(buatPemisahHari());
        for (Pesan p : riwayat) {
            panelPesan.add(buatBarisPesan(p));
        }
        refreshDanScroll();
    }

    private void refreshDanScroll() {
        panelPesan.revalidate();
        panelPesan.repaint();

        SwingUtilities.invokeLater(() -> SwingUtilities.invokeLater(() -> {
            JScrollBar bar = scrollPane.getVerticalScrollBar();
            bar.setValue(bar.getMaximum());
        }));
    }

