    // Kata sapaan di awal kalimat (dibuang supaya pertanyaan di belakangnya tetap dijawab)
    private static final Pattern POLA_SAPAAN = Pattern.compile(
            "^(?:(?:halo+|hallo+|hai+|hi+|hello+|hey+|permisi|"
                    + "selamat\\s+(?:pagi|siang|sore|malam)|kak|min|admin)\\b[\\s,.!?]*)+");
    private static final Pattern POLA_SALAM = Pattern.compile(
            "assalamu\\W?alaikum(?:\\s+wr\\.?\\s*wb\\.?)?");
    private static final Pattern POLA_DELIVERY = Pattern.compile(
            "\\b(?:deliv\\w*|gofood|go food|go-food|gojek|ojol|ojek online|"
                    + "antar|diantar|dianter|antarin|antarkan|pesan online|order online|online order)\\b");

    private static boolean ada(String q, String... kata) {
        String dibungkus = " " + q.replaceAll("[^a-z0-9 ]", " ") + " ";
        for (String k : kata) {
            // kata pendek dicocokkan sebagai kata utuh supaya tidak salah tangkap
            if (k.length() <= 3
                    ? dibungkus.contains(" " + k + " ")
                    : q.contains(k)) {
                return true;
            }
        }
        return false;
    }

    // Cocok hanya kalau kata ditulis utuh ("buka" tidak cocok dengan "bukan")
    private static boolean punyaKata(String q, String... kata) {
        String dibungkus = " " + q.replaceAll("[^a-z0-9 ]", " ") + " ";
        for (String k : kata) {
            if (dibungkus.contains(" " + k + " ")) {
                return true;
            }
        }
        return false;
    }

    // Kalau pelanggan menyebut 2 menu atau lebih ("americano sama latte"), jawab semuanya
    private String jawabanBeberapaMenu(String q) {
        String teks = " " + q.replaceAll("[^a-z0-9 ]", " ").replaceAll("\\s+", " ") + " ";
        Map<String, String> harga = daftarHarga();
        List<String> ketemu = new ArrayList<>();
        for (String nama : harga.keySet()) {
            String n = nama.toLowerCase().replaceAll("[^a-z0-9 ]", " ");
            if (teks.contains(" " + n + " ")) {
                ketemu.add(nama);
            }
        }
        // sebutan lain yang umum dipakai pelanggan
        String[][] alias = {
                {"latte", "Coffee Latte"}, {"kopi latte", "Coffee Latte"},
                {"capuccino", "Cappucino"}, {"cappuccino", "Cappucino"},
                {"capucino", "Cappucino"}, {"mocha", "Mocacino"},
                {"mochaccino", "Mocacino"}, {"macchiato", "Caramel Macchiato"},
                {"machiato", "Caramel Macchiato"}, {"expresso", "Espresso"},
                {"coklat", "Chocolate"}, {"cokelat", "Chocolate"},
                {"kentang", "Kentang Goreng"}, {"platter", "Dialog Platter"},
                {"popmie", "Pop Mie"}, {"milkshake", "Milkshake Vanilla Oreo"},
                {"matcha satu", "Matcha Satu"}, {"salted caramel", "Dialog Salted Caramel"}
        };
        for (String[] al : alias) {
            if (teks.contains(" " + al[0] + " ") && harga.containsKey(al[1])
                    && !ketemu.contains(al[1])) {
                ketemu.add(al[1]);
            }
        }
        List<String> hasil = new ArrayList<>();
        for (String a : ketemu) {
            boolean bagian = false;
            for (String b : ketemu) {
                if (!a.equals(b) && b.toLowerCase().contains(a.toLowerCase())) {
                    bagian = true;
                }
            }
            if (!bagian) {
                hasil.add(a);
            }
        }
        if (hasil.size() < 2) {
            return null;
        }
        StringBuilder sb = new StringBuilder("Ini harganya ya 😊\n");
        for (String h : hasil) {
            sb.append(h).append(" - ").append(harga.get(h)).append("\n");
        }
        return sb.toString().trim();
    }

    private Map<String, String> daftarHarga() {
        Map<String, String> m = new LinkedHashMap<>();
        for (String baris : tampilkanMenu().split("\n")) {
            Matcher mt = POLA_ITEM.matcher(baris);
            if (mt.matches()) {
                m.put(mt.group(1), mt.group(2));
            }
        }
        return m;
    }

    private static int jarakEdit(String a, String b) {
        int[] prev = new int[b.length() + 1];
        int[] cur = new int[b.length() + 1];
        for (int j = 0; j <= b.length(); j++) {
            prev[j] = j;
        }
        for (int i = 1; i <= a.length(); i++) {
            cur[0] = i;
            for (int j = 1; j <= b.length(); j++) {
                int biaya = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
                cur[j] = Math.min(Math.min(cur[j - 1] + 1, prev[j] + 1),
                        prev[j - 1] + biaya);
            }
            int[] t = prev;
            prev = cur;
            cur = t;
        }
        return prev[b.length()];
    }

    // Mencari nama menu yang mirip (salah ketik), misalnya "americanno"
    private String cariMenuMirip(String q) {
        String[] kata = q.replaceAll("[^a-z0-9 ]", " ").trim().split("\\s+");
        String terbaik = null;
        double skorTerbaik = 99;

        for (Map.Entry<String, String> e : daftarHarga().entrySet()) {
            String nama = e.getKey().toLowerCase();
            if (nama.length() < 5) {
                continue;
            }
            int n = nama.split(" ").length;
            int batas = nama.length() <= 9 ? 2 : 3;
            for (int i = 0; i + n <= kata.length; i++) {
                String jendela = String.join(" ",
                        Arrays.copyOfRange(kata, i, i + n));
                int d = jarakEdit(jendela, nama);
                if (d <= batas && (double) d / nama.length() < skorTerbaik) {
                    skorTerbaik = (double) d / nama.length();
                    terbaik = e.getKey();
                }
            }
        }
        if (terbaik == null) {
            return null;
        }
        return "Mungkin maksud kamu \"" + terbaik + "\"?\n"
                + terbaik + " harganya " + daftarHarga().get(terbaik) + ".";
    }

    // Jawaban tebakan (kata kunci longgar) yang disimpan sebagai cadangan kalau AI gagal
    private String saranCadangan = null;

    private String saranLonggar(String q) {

        if (ada(q, "panas", "hangat", "hot", "anget")) {
            return "Soal menu yang bisa disajikan panas, saya belum punya datanya 🙏\n"
                    + "Silakan tanya langsung ke admin Café Dialog:\n" + KONTAK_ADMIN;
        }

        // 2) selera / kebutuhan -> arahkan ke menu yang relevan
        if (ada(q, "murah", "hemat", "budget", "irit", "terjangkau", "mahal")) {
            StringBuilder sb = new StringBuilder("Menu yang paling hemat:\n");
            for (Map.Entry<String, String> e : daftarHarga().entrySet()) {
                int harga = Integer.parseInt(e.getValue().replaceAll("\\D", ""));
                if (harga <= 15000) {
                    sb.append("• ").append(e.getKey()).append(" - ")
                            .append(e.getValue()).append("\n");
                }
            }
            return sb.toString().trim();
        }
        if (ada(q, "pahit", "kuat", "strong", "ngantuk", "melek", "begadang")) {
            return "Kalau mau kopi yang kuat, coba Espresso (Rp15.000), "
                    + "Americano (Rp20.000), atau Long Black (Rp25.000) ☕";
        }
        if (ada(q, "creamy", "susu", "gurih", "lembut")) {
            return menuKopiSusu();
        }
        if (ada(q, "segar", "seger", "dingin", "fresh", "asam", "haus")) {
            return menuKopiSegar();
        }
        if (ada(q, "manis", "dessert", "sweet")) {
            return "Kalau suka yang manis, coba Dialog Salted Caramel, "
                    + "Dialog Butterscotch, Banana Caramel Cheese, "
                    + "atau Milkshake Vanilla Oreo 😋\n"
                    + "Tingkat gula juga bisa direquest.";
        }
        if (ada(q, "tidak suka kopi", "gak suka kopi", "ga suka kopi",
                "nggak suka kopi", "tidak ngopi", "gak ngopi", "ga ngopi",
                "lambung", "asam lambung", "maag", "anak kecil", "buat anak")) {
            return "Kalau tidak ingin kopi, ada menu Bukan Kopi dan Bukan Juga:\n\n"
                    + menuBukanKopi() + "\n\n" + menuBukanJuga();
        }
        if (ada(q, "kopi", "coffee")) {
            return "Ini menu kopi Café Dialog ☕\n\n" + menuKopi()
                    + "\n\nAda juga Kopi Susu dan Kopi Segar. Ketik \"menu\" untuk daftar lengkap.";
        }
        if (ada(q, "teh", "tea")) {
            return "Menu teh kami: Lemon Tea (Rp15.000) dan Lychee Tea (Rp18.000).";
        }
        if (ada(q, "lapar", "ngemil", "cemilan", "camilan", "snack", "makan")) {
            return menuMakanan();
        }

        // 3) suasana & kebutuhan tempat (hanya info yang pasti diketahui)
        if (ada(q, "kerja", "nugas", "tugas", "laptop", "belajar", "wfc",
                "wfh", "skripsi", "meeting", "rapat")) {
            return "Café Dialog menyediakan Wi-Fi dan colokan untuk pelanggan, "
                    + "jadi cocok untuk kerja atau mengerjakan tugas 💻";
        }
        if (ada(q, "nongkrong", "santai", "ngobrol", "kumpul", "suasana",
                "tempatnya", "nyaman", "cocok")) {
            return JAWABAN_NONGKRONG;
        }

        // 4) info yang belum ada -> arahkan ke admin
        if (ada(q, "grabfood", "grab food", "shopee", "take away",
                "takeaway", "bungkus", "dibawa pulang")) {
            return "Untuk saat ini Café Dialog tersedia di GoFood 🛵\n"
                    + "Soal platform lain atau bungkus, silakan tanyakan ke admin ya:\n"
                    + KONTAK_ADMIN;
        }
        if (ada(q, "libur", "tanggal merah", "parkir", "musholla", "mushola",
                "ac", "ramai", "sepi", "kapasitas", "muat", "hewan", "kucing",
                "ulang tahun", "acara", "event", "halal", "vegan", "alergi",
                "kafein", "kalori", "lowongan", "kerja sama", "kerjasama")) {
            return "Untuk info itu saya belum punya datanya 🙏\n"
                    + "Silakan tanya langsung ke admin Café Dialog:\n"
                    + KONTAK_ADMIN;
        }

        return null;
    }

    private String jawabanCadangan(String q) {

        // 1) obrolan ringan
        if (ada(q, "siapa kamu", "siapa anda", "nama kamu", "kamu bot", "kamu siapa")) {
            return "Saya asisten virtual Café Dialog 😊 "
                    + "Saya bisa bantu soal menu, harga, jam buka, alamat, dan fasilitas.";
        }
        if (ada(q, "apa kabar", "lagi apa", "gimana kabar")) {
            return "Baik! 😊 Ada yang bisa saya bantu soal Café Dialog?";
        }
        if (q.equals("ok") || q.equals("oke") || q.equals("sip")
                || q.equals("siap") || q.equals("baik") || q.equals("y")
                || q.equals("ya") || q.equals("iya") || q.equals("mantap")) {
            return "Siap! 👍 Kalau ada yang mau ditanyakan lagi, silakan ya.";
        }
        if (ada(q, "bye", "dadah", "sampai jumpa", "sampai ketemu", "duluan")) {
            return "Terima kasih sudah mampir! Sampai ketemu di Café Dialog ☕";
        }
        if (ada(q, "maaf", "sorry")) {
            return "Tidak apa-apa 😊 Ada yang bisa saya bantu?";
        }
        if (ada(q, "bisa apa", "bantuan", "help", "fitur", "apa saja yang bisa")) {
            return "Saya bisa bantu soal:\n"
                    + "• Menu & harga (contoh: \"harga americano\")\n"
                    + "• Jam buka & alamat\n"
                    + "• Cara pembayaran, Wi-Fi, colokan\n"
                    + "• Rekomendasi menu\n"
                    + "Silakan tanya apa saja 😊";
        }

        // 2-4) tebakan berdasarkan kata kunci longgar. Kalau AI aktif, AI yang menjawab
        //      (supaya pertanyaan umum tidak salah ditangkap). Tebakan ini jadi cadangan.
        String saran = saranLonggar(q);
        if (saran != null) {
            saranCadangan = saran;
            return AWAL_JAWABAN_TIDAK_TAHU + " 🙏\n"
                    + "Saya bisa membantu soal menu dan harga, jam buka, alamat, "
                    + "pembayaran, Wi-Fi, dan rekomendasi. Coba ketik \"menu\".\n"
                    + "Atau tanya admin langsung:\n" + KONTAK_ADMIN;
        }

        // 5) salah ketik nama menu (misalnya "americanno")
        String mirip = cariMenuMirip(q);
        if (mirip != null) {
            return mirip;
        }

        // 6) benar-benar tidak dikenali
        return AWAL_JAWABAN_TIDAK_TAHU + " 🙏\n"
                + "Saya bisa membantu soal menu dan harga, jam buka, alamat, "
                + "pembayaran, Wi-Fi, dan rekomendasi. Coba ketik \"menu\".\n"
                + "Atau tanya admin langsung:\n" + KONTAK_ADMIN;
    }

