    // Gambar cangkir kopi sederhana (dipakai avatar & ikon aplikasi)
    private static void gambarCangkir(Graphics2D g2, double cx, double cy,
                                      double s, Color warna) {
        g2.setColor(warna);
        double w = s * 0.46;
        double h = s * 0.34;
        double x = cx - w / 2 - s * 0.05;
        double y = cy - h / 2 + s * 0.08;

        Area badan = new Area(new RoundRectangle2D.Double(
                x, y, w, h, s * 0.26, s * 0.26));
        badan.add(new Area(new Rectangle2D.Double(x, y, w, h * 0.45)));
        g2.fill(badan);

        g2.setStroke(new BasicStroke((float) (s * 0.065),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g2.draw(new Arc2D.Double(x + w - s * 0.1, y + h * 0.12,
                s * 0.2, h * 0.5, -90, 180, Arc2D.OPEN));

        // alas cangkir
        g2.fill(new RoundRectangle2D.Double(x - s * 0.05, y + h + s * 0.03,
                w + s * 0.1, s * 0.045, s * 0.045, s * 0.045));

        // uap
        double uy = y - s * 0.06;
        for (int i = 0; i < 2; i++) {
            double px = x + w * 0.3 + i * w * 0.4;
            g2.draw(new QuadCurve2D.Double(px, uy,
                    px + s * 0.07, uy - s * 0.07, px, uy - s * 0.14));
        }
    }

    private static Image buatIkonAplikasi() {
        BufferedImage img = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = img.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setColor(new Color(215, 170, 120));
        g2.fillOval(1, 1, 62, 62);
        gambarCangkir(g2, 32, 32, 64, WARNA_HEADER);
        g2.dispose();
        return img;
    }

    // Bubble chat: sudut membulat, bayangan lembut, isi menu yang rapi
    private static class BubblePanel extends JPanel {

        private final boolean dariUser;
        private final boolean mengetik;
        private Timer animasi;

        BubblePanel(String teks, boolean dariUser,
                    String waktuKirim, boolean mengetik) {
            this(teks, dariUser, waktuKirim, mengetik, null);
        }

        BubblePanel(String teks, boolean dariUser,
                    String waktuKirim, boolean mengetik, String gambar) {

            this.dariUser = dariUser;
            this.mengetik = mengetik;
            setOpaque(false);

            if (mengetik) {
                setPreferredSize(new Dimension(72, 42));
                return;
            }

            setLayout(new BorderLayout(0, 3));
            setBorder(BorderFactory.createEmptyBorder(9, 13, 9, 13));
            add(buatIsi(teks, dariUser, gambar), BorderLayout.CENTER);

            if (waktuKirim != null) {
                JLabel waktu = new JLabel(waktuKirim);
                waktu.setFont(FONT_WAKTU);
                waktu.setForeground(dariUser
                        ? new Color(214, 250, 226) : WARNA_WAKTU);
                waktu.setHorizontalAlignment(SwingConstants.RIGHT);
                add(waktu, BorderLayout.SOUTH);
            }
        }

        // Animasi titik hanya jalan selama bubble tampil di layar
        @Override
        public void addNotify() {
            super.addNotify();
            if (mengetik && animasi == null) {
                animasi = new Timer(45, e -> repaint());
                animasi.start();
            }
        }

        @Override
        public void removeNotify() {
            if (animasi != null) {
                animasi.stop();
                animasi = null;
            }
            super.removeNotify();
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON);

            int w = getWidth() - 1;
            int h = getHeight() - 4;   // sisakan ruang untuk bayangan

            // bayangan lembut
            for (int i = 3; i >= 1; i--) {
                g2.setColor(new Color(70, 45, 25, 11));
                g2.fill(new RoundRectangle2D.Float(
                        0, i, w, h, 20, 20));
            }

            // badan bubble
            if (dariUser) {
                g2.setPaint(new GradientPaint(
                        0, 0, WARNA_USER_ATAS, 0, h, WARNA_USER_BAWAH));
            } else {
                g2.setPaint(WARNA_BUBBLE_BOT);
            }
            g2.fill(new RoundRectangle2D.Float(0, 0, w, h, 20, 20));

            // "ekor" kecil di pojok atas
            if (dariUser) {
                g2.fillRect(w - 10, 0, 10, 10);
            } else {
                g2.fillRect(0, 0, 10, 10);
            }

            // tiga titik "sedang mengetik"
            if (mengetik) {
                long t = System.currentTimeMillis();
                for (int i = 0; i < 3; i++) {
                    double fase = t / 170.0 - i * 0.8;
                    double naik = Math.max(0, Math.sin(fase)) * 5;
                    g2.setColor(new Color(165, 150, 138));
                    g2.fill(new Ellipse2D.Double(
                            w / 2.0 + (i - 1) * 14 - 4,
                            h / 2.0 - 4 - naik, 8, 8));
                }
            }

            g2.dispose();
            super.paintComponent(g);
        }

        // Memecah teks jawaban: judul kategori, baris harga, dan teks biasa
        private static JComponent buatIsi(String teks, boolean dariUser,
                                          String namaGambar) {

            Color warnaTeks = dariUser ? Color.WHITE : WARNA_TEKS;
            int batas = maxLebarBubble - 26;

            JLabel pengukur = new JLabel();
            FontMetrics fm = pengukur.getFontMetrics(FONT_CHAT);
            FontMetrics fmTebal =
                    pengukur.getFontMetrics(FONT_CHAT.deriveFont(Font.BOLD));

            String[] baris = teks.isEmpty() ? new String[0] : teks.split("\n", -1);

            List<BufferedImage> fotos = new ArrayList<>();
            if (namaGambar != null) {
                for (String n : namaGambar.split(",")) {
                    BufferedImage f = muatGambar(n.trim());
                    if (f != null) {
                        fotos.add(f);
                    }
                }
            }
            int lebarFoto = Math.min(batas, 360);

            // 1) hitung lebar bubble dari baris terpanjang
            int lebar = 60;
            boolean adaMenu = false;
            for (String b : baris) {
                Matcher judul = POLA_JUDUL.matcher(b);
                Matcher item = POLA_ITEM.matcher(b);
                Matcher harga = POLA_HARGA.matcher(b);
                if (judul.matches()) {
                    adaMenu = true;
                    lebar = Math.max(lebar, fmTebal.stringWidth(judul.group(1)) + 8);
                } else if (item.matches()) {
                    adaMenu = true;
                    lebar = Math.max(lebar, fm.stringWidth(item.group(1))
                            + 32 + fmTebal.stringWidth(item.group(2)));
                } else if (harga.matches()) {
                    adaMenu = true;
                    lebar = Math.max(lebar, fm.stringWidth(harga.group(1))
                            + 32 + fmTebal.stringWidth(harga.group(2)));
                } else {
                    lebar = Math.max(lebar, fm.stringWidth(b) + 4);
                }
            }
            if (adaMenu) {
                lebar = Math.max(lebar, 230);
            }
            if (fotos.size() == 1) {
                BufferedImage foto = fotos.get(0);
                double skala = Math.min((double) lebarFoto / foto.getWidth(),
                        440.0 / foto.getHeight());
                lebar = Math.max(lebar, (int) Math.round(foto.getWidth() * skala));
            } else if (fotos.size() > 1) {
                lebar = Math.max(lebar, lebarFoto);
            }
            lebar = Math.min(lebar, batas);

            // 2) susun komponen tiap baris
            JPanel kolom = new JPanel();
            kolom.setOpaque(false);
            kolom.setLayout(new BoxLayout(kolom, BoxLayout.Y_AXIS));

            // foto di bagian atas bubble (bisa diklik untuk memperbesar)
            String judulDialog = judulFoto(namaGambar);
            if (fotos.size() == 1) {
                GambarKlik gk = new GambarKlik(fotos.get(0), lebar, 440,
                        fotos, 0, judulDialog);
                gk.setAlignmentX(Component.LEFT_ALIGNMENT);
                kolom.add(gk);
                kolom.add(Box.createVerticalStrut(6));
            } else if (fotos.size() > 1) {
                // beberapa foto: ditampilkan berjajar sebagai thumbnail
                int jarak = 6;
                int n = fotos.size();
                int lebarThumb = (lebar - jarak * (n - 1)) / n;
                JPanel jajar = new JPanel();
                jajar.setOpaque(false);
                jajar.setLayout(new BoxLayout(jajar, BoxLayout.X_AXIS));
                for (int i = 0; i < n; i++) {
                    if (i > 0) {
                        jajar.add(Box.createRigidArea(new Dimension(jarak, 0)));
                    }
                    jajar.add(new GambarKlik(fotos.get(i), lebarThumb, 170,
                            fotos, i, judulDialog));
                }
                jajar.setAlignmentX(Component.LEFT_ALIGNMENT);
                Dimension d = jajar.getPreferredSize();
                tetapkanUkuran(jajar, d.width, d.height);
                kolom.add(jajar);
                kolom.add(Box.createVerticalStrut(6));
            }

            for (String b : baris) {
                Matcher judul = POLA_JUDUL.matcher(b);
                Matcher item = POLA_ITEM.matcher(b);
                Matcher harga = POLA_HARGA.matcher(b);
                JComponent c;

                if (judul.matches()) {
                    JLabel l = new JLabel(judul.group(1));
                    l.setFont(new Font(NAMA_FONT, Font.BOLD, 12));
                    l.setForeground(WARNA_JUDUL_MENU);
                    l.setBorder(BorderFactory.createCompoundBorder(
                            BorderFactory.createEmptyBorder(7, 0, 4, 0),
                            BorderFactory.createCompoundBorder(
                                    BorderFactory.createMatteBorder(0, 0, 1, 0, WARNA_GARIS),
                                    BorderFactory.createEmptyBorder(0, 0, 3, 0))));
                    c = l;
                    tetapkanUkuran(c, lebar, l.getPreferredSize().height);
                } else if (item.matches()) {
                    c = new BarisHarga(item.group(1), item.group(2), false);
                    tetapkanUkuran(c, lebar, c.getPreferredSize().height);
                } else if (harga.matches()) {
                    c = new BarisHarga(harga.group(1), harga.group(2), true);
                    tetapkanUkuran(c, lebar, c.getPreferredSize().height);
                } else if (b.isEmpty()) {
                    c = (JComponent) Box.createVerticalStrut(7);
                } else {
                    JTextArea t = new JTextArea(b);
                    t.setEditable(false);
                    t.setOpaque(false);
                    t.setBorder(null);
                    t.setFont(FONT_CHAT);
                    t.setForeground(warnaTeks);
                    t.setLineWrap(true);
                    t.setWrapStyleWord(true);
                    t.setSize(lebar, Short.MAX_VALUE);
                    tetapkanUkuran(t, lebar, t.getPreferredSize().height);
                    c = t;
                }

                c.setAlignmentX(Component.LEFT_ALIGNMENT);
                kolom.add(c);
            }
            return kolom;
        }

        private static void tetapkanUkuran(JComponent c, int w, int h) {
            Dimension d = new Dimension(w, h);
            c.setPreferredSize(d);
            c.setMaximumSize(d);
        }
    }

    // Foto di dalam bubble: sudut membulat, klik untuk memperbesar
    private static class GambarKlik extends JComponent {

        private final BufferedImage img;
        private final int w;
        private final int h;
        private final List<BufferedImage> galeri;
        private final int indeks;
        private final String judul;

        GambarKlik(BufferedImage img, int lebarMaks, int tinggiMaks,
                   List<BufferedImage> galeri, int indeks, String judul) {
            this.img = img;
            this.galeri = galeri;
            this.indeks = indeks;
            this.judul = judul;
            double skala = Math.min((double) lebarMaks / img.getWidth(),
                    (double) tinggiMaks / img.getHeight());
            this.w = Math.max(1, (int) Math.round(img.getWidth() * skala));
            this.h = Math.max(1, (int) Math.round(img.getHeight() * skala));
            Dimension d = new Dimension(w, h);
            setPreferredSize(d);
            setMaximumSize(d);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            setToolTipText("Klik untuk memperbesar");
            addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    perbesar();
                }
            });
        }

        private BufferedImage cache;

        private void perbesar() {
            Dimension layar = Toolkit.getDefaultToolkit().getScreenSize();
            Window pemilik = SwingUtilities.getWindowAncestor(this);
            final int[] kini = {indeks};
            final int total = galeri.size();

            final JDialog dialog = new JDialog(pemilik, judul,
                    Dialog.ModalityType.APPLICATION_MODAL);
            final JLabel gambar = new JLabel();
            gambar.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

            final Runnable tampilkan = () -> {
                BufferedImage f = galeri.get(kini[0]);
                double skala = Math.min(1.0, Math.min(
                        (layar.width * 0.9) / f.getWidth(),
                        (layar.height * 0.85) / f.getHeight()));
                int bw = (int) (f.getWidth() * skala);
                int bh = (int) (f.getHeight() * skala);
                gambar.setIcon(new ImageIcon(skalakanHalus(f, bw, bh)));
                dialog.setTitle(total > 1
                        ? judul + " (" + (kini[0] + 1) + "/" + total
                                + ") - klik foto untuk berikutnya"
                        : judul);
            };
            tampilkan.run();

            gambar.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    if (total > 1) {
                        kini[0] = (kini[0] + 1) % total;
                        tampilkan.run();
                        dialog.pack();
                        dialog.setLocationRelativeTo(pemilik);
                    } else {
                        dialog.dispose();
                    }
                }
            });
            dialog.getRootPane().registerKeyboardAction(e -> dialog.dispose(),
                    KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0),
                    JComponent.WHEN_IN_FOCUSED_WINDOW);
            dialog.setContentPane(gambar);
            dialog.pack();
            dialog.setResizable(false);
            dialog.setLocationRelativeTo(pemilik);
            dialog.setVisible(true);
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON);

            // perkecil sekali saja sesuai piksel layar asli (tajam di layar HiDPI)
            double sc = Math.max(1.0, g2.getTransform().getScaleX());
            int tw = (int) Math.round(w * sc);
            int th = (int) Math.round(h * sc);
            if (cache == null || cache.getWidth() != tw || cache.getHeight() != th) {
                cache = skalakanHalus(img, tw, th);
            }

            g2.setClip(new RoundRectangle2D.Float(0, 0, w, h, 14, 14));
            g2.drawImage(cache, 0, 0, w, h, null);
            g2.dispose();
        }
    }

    // Memperkecil gambar bertahap (dibagi dua berulang) supaya hasilnya tajam
    private static BufferedImage skalakanHalus(BufferedImage asal, int lebar, int tinggi) {
        BufferedImage hasil = asal;
        int w = asal.getWidth();
        int h = asal.getHeight();
        if (lebar >= w || tinggi >= h) {
            w = lebar;
            h = tinggi;
        }
        while (w > lebar || h > tinggi) {
            w = Math.max(lebar, w / 2);
            h = Math.max(tinggi, h / 2);
            hasil = langkahSkala(hasil, w, h);
        }
        if (hasil.getWidth() != lebar || hasil.getHeight() != tinggi) {
            hasil = langkahSkala(hasil, lebar, tinggi);
        }
        return hasil;
    }

    private static BufferedImage langkahSkala(BufferedImage src, int w, int h) {
        BufferedImage dst = new BufferedImage(Math.max(1, w), Math.max(1, h),
                BufferedImage.TYPE_INT_RGB);
        Graphics2D g2 = dst.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
                RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        g2.setRenderingHint(RenderingHints.KEY_RENDERING,
                RenderingHints.VALUE_RENDER_QUALITY);
        g2.drawImage(src, 0, 0, dst.getWidth(), dst.getHeight(), null);
        g2.dispose();
        return dst;
    }

    // Satu baris menu: nama di kiri, harga di kanan, dihubungkan titik-titik
    private static class BarisHarga extends JComponent {

        private final String nama;
        private final String harga;
        private final boolean tebalNama;

        BarisHarga(String nama, String harga, boolean tebalNama) {
            this.nama = nama;
            this.harga = harga;
            this.tebalNama = tebalNama;
            Font f = FONT_CHAT;
            int h = getFontMetrics(f).getHeight() + 5;
            setPreferredSize(new Dimension(100, h));
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                    RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON);

            Font fNama = tebalNama ? FONT_CHAT.deriveFont(Font.BOLD) : FONT_CHAT;
            Font fHarga = FONT_CHAT.deriveFont(Font.BOLD);
            FontMetrics fmN = g2.getFontMetrics(fNama);
            FontMetrics fmH = g2.getFontMetrics(fHarga);
            int y = (getHeight() - fmN.getHeight()) / 2 + fmN.getAscent();

            g2.setFont(fNama);
            g2.setColor(WARNA_TEKS);
            g2.drawString(nama, 0, y);

            int xHarga = getWidth() - fmH.stringWidth(harga);
            g2.setFont(fHarga);
            g2.setColor(WARNA_AKSEN.darker());
            g2.drawString(harga, xHarga, y);

            // garis titik-titik penghubung
            int mulai = fmN.stringWidth(nama) + 8;
            int akhir = xHarga - 8;
            if (akhir > mulai) {
                g2.setColor(new Color(205, 192, 178));
                g2.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND,
                        BasicStroke.JOIN_ROUND, 1f, new float[]{0.5f, 4f}, 0f));
                g2.drawLine(mulai, y, akhir, y);
            }
            g2.dispose();
        }
    }

