    // ==================================================
    // AI LOKAL (Ollama) - dipanggil hanya kalau aturan di atas tidak tahu jawabannya
    // ==================================================

    private static class AiLokal {

        static final String URL_OLLAMA = "http://localhost:11434/api/chat";
        static final String MODEL_BAWAAN = "llama3.2:1b";
        // urutan pilihan: yang lebih besar jawabannya jauh lebih baik dan lebih rapi
        private static final String[] MODEL_PILIHAN = {
                "qwen2.5:7b", "llama3.1:8b", "qwen2.5:3b", "llama3.2:3b",
                "gemma2:2b", "qwen2.5:1.5b", "llama3.2:1b"};
        private static volatile String modelTerpilih;

        // Memilih model terbaik yang sudah diunduh di Ollama
        private static String pilihModel() {
            if (modelTerpilih != null) {
                return modelTerpilih;
            }
            try {
                java.net.http.HttpResponse<String> r = KLIEN.send(
                        java.net.http.HttpRequest.newBuilder()
                                .uri(java.net.URI.create("http://localhost:11434/api/tags"))
                                .timeout(java.time.Duration.ofSeconds(5)).GET().build(),
                        java.net.http.HttpResponse.BodyHandlers.ofString());
                List<String> ada = new ArrayList<>();
                Matcher mt = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]+)\"").matcher(r.body());
                while (mt.find()) {
                    ada.add(mt.group(1));
                }
                for (String m : MODEL_PILIHAN) {
                    if (ada.contains(m) || ada.contains(m + ":latest")) {
                        return modelTerpilih = m;
                    }
                }
                if (!ada.isEmpty()) {
                    return modelTerpilih = ada.get(0);
                }
            } catch (Exception ignored) {
                // Ollama belum aktif: nanti gagal di chat() dan dipakai jawaban cadangan
            }
            return MODEL_BAWAAN;
        }

        // Contoh tanya-jawab supaya model kecil meniru gaya jawaban yang benar
        private static final String[][] CONTOH = {
                {"Ada teh nggak?",
                        "Ada. Lemon Tea Rp15.000 dan Lychee Tea Rp18.000. Mau coba salah satunya?"},
                {"Berapa 12 dikali 12?",
                        "12 dikali 12 hasilnya 144."},
                {"Apa ibu kota Jepang?",
                        "Ibu kota Jepang adalah Tokyo."},
                {"Parkirannya luas?",
                        "Maaf, saya belum punya info itu. Silakan tanya admin lewat WhatsApp 085789678022."}
        };

        private static final java.net.http.HttpClient KLIEN =
                java.net.http.HttpClient.newBuilder()
                        .connectTimeout(java.time.Duration.ofSeconds(3))
                        .build();

        // sistem   = instruksi + data Café Dialog (satu-satunya sumber jawaban)
        // riwayat  = pasangan {"user"/"assistant", isi} sebelum pesan ini
        static String chat(String pesan, List<String[]> riwayat, String sistem)
                throws Exception {

            StringBuilder msgs = new StringBuilder();
            msgs.append("{\"role\":\"system\",\"content\":").append(json(sistem)).append("}");
            for (String[] c : CONTOH) {
                msgs.append(",{\"role\":\"user\",\"content\":").append(json(c[0])).append("}")
                        .append(",{\"role\":\"assistant\",\"content\":").append(json(c[1])).append("}");
            }
            for (String[] r : riwayat) {
                msgs.append(",{\"role\":\"").append(r[0])
                        .append("\",\"content\":").append(json(r[1])).append("}");
            }
            msgs.append(",{\"role\":\"user\",\"content\":").append(json(pesan)).append("}");

            String body = "{\"model\":" + json(pilihModel())
                    + ",\"stream\":false,\"keep_alive\":\"30m\""
                    + ",\"options\":{\"temperature\":0.3,\"top_p\":0.9"
                    + ",\"repeat_penalty\":1.1,\"num_predict\":400,\"num_ctx\":6144}"
                    + ",\"messages\":[" + msgs + "]}";

            java.net.http.HttpRequest req = java.net.http.HttpRequest.newBuilder()
                    .uri(java.net.URI.create(URL_OLLAMA))
                    .timeout(java.time.Duration.ofSeconds(180))
                    .header("Content-Type", "application/json; charset=utf-8")
                    .POST(java.net.http.HttpRequest.BodyPublishers.ofString(
                            body, java.nio.charset.StandardCharsets.UTF_8))
                    .build();

            java.net.http.HttpResponse<String> res = KLIEN.send(req,
                    java.net.http.HttpResponse.BodyHandlers.ofString(
                            java.nio.charset.StandardCharsets.UTF_8));
            if (res.statusCode() != 200) {
                throw new java.io.IOException("Ollama HTTP " + res.statusCode()
                        + ": " + res.body());
            }
            return bersihkan(ambilIsi(res.body()));
        }

        // Teks polos untuk bubble: buang markdown, batasi panjang
        private static String bersihkan(String t) {
            if (t == null) {
                return null;
            }
            t = t.replace("**", "").replace("__", "")
                    .replaceAll("(?m)^\\s*[*-]\\s+", "• ")
                    .replaceAll("(?m)^#+\\s*", "")
                    .trim();
            if (t.length() > 1200) {
                int titik = t.lastIndexOf('.', 1200);
                t = titik > 300 ? t.substring(0, titik + 1) : t.substring(0, 1200) + "...";
            }
            return t;
        }

        private static String json(String s) {
            StringBuilder sb = new StringBuilder("\"");
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                switch (c) {
                    case '"':  sb.append("\\\""); break;
                    case '\\': sb.append("\\\\"); break;
                    case '\n': sb.append("\\n"); break;
                    case '\r': sb.append("\\r"); break;
                    case '\t': sb.append("\\t"); break;
                    default:
                        if (c < 0x20) {
                            sb.append(String.format("\\u%04x", (int) c));
                        } else {
                            sb.append(c);
                        }
                }
            }
            return sb.append('"').toString();
        }

        // Mengambil isi "message":{"content":"..."} dari balasan Ollama
        private static String ambilIsi(String js) {
            int m = js.indexOf("\"message\"");
            if (m < 0) {
                return null;
            }
            int k = js.indexOf("\"content\"", m);
            if (k < 0) {
                return null;
            }
            int i = js.indexOf('"', js.indexOf(':', k) + 1);
            if (i < 0) {
                return null;
            }
            StringBuilder sb = new StringBuilder();
            for (i = i + 1; i < js.length(); i++) {
                char c = js.charAt(i);
                if (c == '"') {
                    break;
                }
                if (c == '\\' && i + 1 < js.length()) {
                    char n = js.charAt(++i);
                    switch (n) {
                        case 'n': sb.append('\n'); break;
                        case 't': sb.append('\t'); break;
                        case 'r': break;
                        case 'u':
                            if (i + 4 < js.length()) {
                                sb.append((char) Integer.parseInt(
                                        js.substring(i + 1, i + 5), 16));
                                i += 4;
                            }
                            break;
                        default: sb.append(n);
                    }
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }
    }

